import{_ as s,o as n,c as t,j as e,a,aj as r}from"./chunks/framework.DzixuiF-.js";const l="/DWES/img/logo-cc.png",h=JSON.parse('{"title":"Desenvolupament Web en Entorn Servidor","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),c={name:"index.md"};function o(d,i,p,u,m,g){return n(),t("div",null,i[0]||(i[0]=[e("h1",{id:"desenvolupament-web-en-entorn-servidor",tabindex:"-1"},[a("Desenvolupament Web en Entorn Servidor "),e("a",{class:"header-anchor",href:"#desenvolupament-web-en-entorn-servidor","aria-label":'Permalink to "Desenvolupament Web en Entorn Servidor"'},"​")],-1),e("h2",{id:"cfgs-daw-2n-curs",tabindex:"-1"},[a("CFGS DAW- 2n Curs "),e("a",{class:"header-anchor",href:"#cfgs-daw-2n-curs","aria-label":'Permalink to "CFGS DAW- 2n Curs"'},"​")],-1),e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"📋 Informació del Curs"),e("p",null,[e("strong",null,"Profesor:"),a(" Eloy Gutiérrez"),e("br"),e("strong",null,"Año Académico:"),a(" 2026-2027"),e("br"),e("strong",null,"Centro:"),a(" IES María Enríquez"),e("br"),e("strong",null,"Módulo:"),a(" Desenvolupament Web en Entorn Servidor"),e("br"),e("strong",null,"Duración:"),a(" 200 horas")]),e("p",null,[e("img",{src:l,alt:"Logo CC",logo:""})])],-1),r('<h2 id="descripcio-del-curs" tabindex="-1">Descripció del curs <a class="header-anchor" href="#descripcio-del-curs" aria-label="Permalink to &quot;Descripció del curs&quot;">​</a></h2><p>Aquest mòdul proporciona els coneixements necessaris per a dissenyar, desenvolupar i implementar la lògica de negoci i la gestió de dades en el costat del servidor (backend). Aprendràs a construir aplicacions web dinàmiques, segures i escalables que processen peticions, interactuen amb bases de dades i subministren serveis a les interfícies d&#39;usuari.</p><h2 id="continguts-clau" tabindex="-1">Continguts clau <a class="header-anchor" href="#continguts-clau" aria-label="Permalink to &quot;Continguts clau&quot;">​</a></h2><p>Els continguts es centren en les àrees fonamentals del desenvolupament backend modern:</p><ul><li><p>Arquitectura i Llenguatges Server-Side: Desenvolupament de lògica de negoci en el servidor utilitzant llenguatges com PHP o Node.js. Processament de peticions HTTP, gestió de formularis, sessions i galetes (cookies) d&#39;usuari.</p></li><li><p>Accés a Dades i Persistència: Integració amb bases de dades relacionals (com MySQL/PostgreSQL) i no relacionals. Ús d&#39;ORMs i consultes segures per a la gestió del cicle de vida de les dades (CRUD).</p></li><li><p>Desenvolupament d&#39;APIs RESTful i JSON: Disseny i implementació de serveis web i APIs REST que serveixen informació en format JSON per a connectar el servidor amb clients frontend o aplicacions mòbils.</p></li><li><p>Seguretat, Autenticació i Desplegament: Implementació de mecanismes d&#39;autenticació (JWT, OAuth), protecció contra vulnerabilitats comunes (Injecció SQL, XSS, CSRF) i desplegament d&#39;aplicacions mitjançant eines de contenidorització com Docker.</p></li></ul><h2 id="importancia" tabindex="-1">Importància <a class="header-anchor" href="#importancia" aria-label="Permalink to &quot;Importància&quot;">​</a></h2><p>El mòdul de DWES és un dels pilars centrals del perfil professional en DAW. Mentre que en el primer any vas aprendre a estructurar i intercanviar informació, en aquest curs adquiriràs la capacitat de construir el motor que dóna vida a les aplicacions web complexes, preparant el teu perfil per a rols de desenvolupador backend o full-stack.</p><h2 class="animate-title" id="resultats-d-aprenentatge-i-criteris-d-avaluacio" tabindex="-1">Resultats d&#39;aprenentatge i criteris d&#39;avaluació <a class="header-anchor" href="#resultats-d-aprenentatge-i-criteris-d-avaluacio" aria-label="Permalink to &quot;Resultats d&#39;aprenentatge i criteris d&#39;avaluació {.animate-title}&quot;">​</a></h2><details class="details custom-block"><summary>📋 Resultats d&#39;aprenentatge i criteris d&#39;avaluació</summary><h4 id="ra1-selecciona-les-arquitectures-i-tecnologies-de-programacio-web-en-entorn-servidor-analitzant-les-seues-capacitats-i-caracteristiques-propies" tabindex="-1">RA1. Selecciona les arquitectures i tecnologies de programació Web en entorn servidor, analitzant les seues capacitats i característiques pròpies. <a class="header-anchor" href="#ra1-selecciona-les-arquitectures-i-tecnologies-de-programacio-web-en-entorn-servidor-analitzant-les-seues-capacitats-i-caracteristiques-propies" aria-label="Permalink to &quot;RA1. Selecciona les arquitectures i tecnologies de programació Web en entorn servidor, analitzant les seues capacitats i característiques pròpies.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han caracteritzat i diferenciat els models d&#39;execució de codi en el servidor i en el client Web.</p></li><li><p>b) S&#39;han reconegut els avantatges que proporciona la generació dinàmica de pàgines Web i les seues diferències amb la inclusió de sentències de guions a l&#39;interior de les pàgines Web.</p></li><li><p>c) S&#39;han identificat els mecanismes d&#39;execució de codi en els servidors Web.</p></li><li><p>d) S&#39;han reconegut les funcionalitats que aporten els servidors d&#39;aplicacions i la seua integració amb els servidors Web.</p></li><li><p>e) S&#39;han identificat i caracteritzat els principals llenguatges i tecnologies relacionats amb la programació Web en entorn servidor.</p></li><li><p>f) S&#39;han verificat els mecanismes d&#39;integració dels llenguatges de marques amb els llenguatges de programació en entorn servidor.</p></li><li><p>g) S&#39;han reconegut i avaluat les eines de programació en entorn servidor.</p></li></ul><h4 id="ra-2-escriu-sentencies-executables-per-un-servidor-web-reconeixent-i-aplicant-procediments-d-integracio-del-codi-en-llenguatges-de-marques" tabindex="-1">RA 2. Escriu sentències executables per un servidor Web reconeixent i aplicant procediments d&#39;integració del codi en llenguatges de marques. <a class="header-anchor" href="#ra-2-escriu-sentencies-executables-per-un-servidor-web-reconeixent-i-aplicant-procediments-d-integracio-del-codi-en-llenguatges-de-marques" aria-label="Permalink to &quot;RA 2. Escriu sentències executables per un servidor Web reconeixent i aplicant procediments d&#39;integració del codi en llenguatges de marques.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han reconegut els mecanismes de generació de pàgines Web a partir de llenguatges de marques amb codi embegut.</p></li><li><p>b) S&#39;han identificat les principals tecnologies associades.</p></li><li><p>c) S&#39;han utilitzat etiquetes per a la inclusió de codi en el llenguatge de marques.</p></li><li><p>d) S&#39;ha reconegut la sintaxi del llenguatge de programació que s&#39;ha d&#39;utilitzar.</p></li><li><p>e) S&#39;han escrit sentències simples i s&#39;han comprovat els seus efectes en el document resultant.</p></li><li><p>f) S&#39;han utilitzat directives per a modificar el comportament predeterminat.</p></li><li><p>g) S&#39;han utilitzat els diferents tipus de variables i operadors disponibles en el llenguatge.</p></li><li><p>h) S&#39;han identificat els àmbits d&#39;utilització de les variables.</p></li></ul><h4 id="ra-3-escriu-blocs-de-sentencies-embeguts-en-llenguatges-de-marques-seleccionant-i-utilitzant-les-estructures-de-programacio" tabindex="-1">RA 3. Escriu blocs de sentències embeguts en llenguatges de marques, seleccionant i utilitzant les estructures de programació. <a class="header-anchor" href="#ra-3-escriu-blocs-de-sentencies-embeguts-en-llenguatges-de-marques-seleccionant-i-utilitzant-les-estructures-de-programacio" aria-label="Permalink to &quot;RA 3. Escriu blocs de sentències embeguts en llenguatges de marques, seleccionant i utilitzant les estructures de programació.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han utilitzat mecanismes de decisió en la creació de blocs de sentències.</p></li><li><p>b) S&#39;han utilitzat bucles i s&#39;ha verificat el seu funcionament.</p></li><li><p>c) S&#39;han utilitzat “arrays” per a emmagatzemar i recuperar conjunts de dades.</p></li><li><p>d) S&#39;han creat i utilitzat funcions.</p></li><li><p>e) S&#39;han utilitzat formularis web per a interactuar amb l&#39;usuari del navegador web.</p></li><li><p>f) S&#39;han emprat mètodes per a recuperar la informació introduïda en el formulari.</p></li><li><p>g) S&#39;han afegit comentaris al codi.</p></li></ul><h4 id="ra-4-desenvolupa-aplicacions-web-embegudes-en-llenguatges-de-marques-analitzant-i-incorporant-funcionalitats-segons-especificacions" tabindex="-1">RA 4. Desenvolupa aplicacions Web embegudes en llenguatges de marques analitzant i incorporant funcionalitats segons especificacions. <a class="header-anchor" href="#ra-4-desenvolupa-aplicacions-web-embegudes-en-llenguatges-de-marques-analitzant-i-incorporant-funcionalitats-segons-especificacions" aria-label="Permalink to &quot;RA 4. Desenvolupa aplicacions Web embegudes en llenguatges de marques analitzant i incorporant funcionalitats segons especificacions.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han identificat els mecanismes disponibles per al manteniment de la informació que concerneix un client web concret i s&#39;han assenyalat els seus avantatges.</p></li><li><p>b) S&#39;han utilitzat mecanismes per a mantindre l&#39;estat de les aplicacions web.</p></li><li><p>c) S&#39;han utilitzat mecanismes per a emmagatzemar informació en el client web i per a recuperar el seu contingut.</p></li><li><p>d) S&#39;han identificat i caracteritzat els mecanismes disponibles per a l&#39;autenticació d&#39;usuaris.</p></li><li><p>e) S&#39;han escrit aplicacions que integren mecanismes d&#39;autenticació d&#39;usuaris.</p></li><li><p>f) S&#39;han utilitzat eines i entorns per a facilitar la programació, prova i depuració del codi.</p></li></ul><h4 id="ra-5-desenvolupa-aplicacions-web-identificant-i-aplicant-mecanismes-per-a-separar-el-codi-de-presentacio-de-la-logica-de-negoci" tabindex="-1">RA 5. Desenvolupa aplicacions Web identificant i aplicant mecanismes per a separar el codi de presentació de la lògica de negoci. <a class="header-anchor" href="#ra-5-desenvolupa-aplicacions-web-identificant-i-aplicant-mecanismes-per-a-separar-el-codi-de-presentacio-de-la-logica-de-negoci" aria-label="Permalink to &quot;RA 5. Desenvolupa aplicacions Web identificant i aplicant mecanismes per a separar el codi de presentació de la lògica de negoci.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han identificat els avantatges de separar la lògica de negoci dels aspectes de presentació de l&#39;aplicació.</p></li><li><p>b) S&#39;han analitzat tecnologies i mecanismes que permeten realitzar aquesta separació i les seues característiques principals.</p></li><li><p>c) S&#39;han utilitzat objectes i controls en el servidor per a generar l&#39;aspecte visual de l&#39;aplicació web en el client.</p></li><li><p>d) S&#39;han utilitzat formularis generats de manera dinàmica per a respondre als esdeveniments de l&#39;aplicació Web.</p></li><li><p>e) S&#39;han identificat i aplicat els paràmetres relatius a la configuració de l&#39;aplicació Web.</p></li><li><p>f) S&#39;han escrit aplicacions Web amb manteniment d&#39;estat i separació de la lògica de negoci.</p></li><li><p>g) S&#39;han aplicat els principis de la programació orientada a objectes.</p></li><li><p>h) S&#39;ha provat i documentat el codi.</p></li></ul><h4 id="ra-6-desenvolupa-aplicacions-d-acces-a-magatzems-de-dades-aplicant-mesures-per-a-mantindre-la-seguretat-i-la-integritat-de-la-informacio" tabindex="-1">RA 6. Desenvolupa aplicacions d&#39;accés a magatzems de dades, aplicant mesures per a mantindre la seguretat i la integritat de la informació. <a class="header-anchor" href="#ra-6-desenvolupa-aplicacions-d-acces-a-magatzems-de-dades-aplicant-mesures-per-a-mantindre-la-seguretat-i-la-integritat-de-la-informacio" aria-label="Permalink to &quot;RA 6. Desenvolupa aplicacions d&#39;accés a magatzems de dades, aplicant mesures per a mantindre la seguretat i la integritat de la informació.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han analitzat les tecnologies que permeten l&#39;accés mitjançant programació a la informació disponible en magatzems de dades.</p></li><li><p>b) S&#39;han creat aplicacions que establisquen connexions amb bases de dades.</p></li><li><p>c) S&#39;ha recuperat informació emmagatzemada en bases de dades.</p></li><li><p>d) S&#39;ha publicat en aplicacions web la informació recuperada.</p></li><li><p>e) S&#39;han utilitzat conjunts de dades per a emmagatzemar la informació.</p></li><li><p>f) S&#39;han creat aplicacions web que permeten l&#39;actualització i l&#39;eliminació d&#39;informació disponible en una base de dades.</p></li><li><p>g) S&#39;han provat i documentat les aplicacions.</p></li></ul><h4 id="ra7-desenvolupa-serveis-web-reutilitzables-i-accessibles-mitjancant-protocols-web-verificant-el-seu-funcionament" tabindex="-1">RA7. Desenvolupa serveis web reutilitzables i accessibles mitjançant protocols web, verificant el seu funcionament. <a class="header-anchor" href="#ra7-desenvolupa-serveis-web-reutilitzables-i-accessibles-mitjancant-protocols-web-verificant-el-seu-funcionament" aria-label="Permalink to &quot;RA7. Desenvolupa serveis web reutilitzables i accessibles mitjançant protocols web, verificant el seu funcionament.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han reconegut les característiques pròpies i l&#39;àmbit d&#39;aplicació dels serveis web.</p></li><li><p>b) S&#39;han reconegut els avantatges d&#39;utilitzar serveis web per a proporcionar accés a funcionalitats incorporades a la lògica de negoci d&#39;una aplicació.</p></li><li><p>c) S&#39;han identificat les tecnologies i els protocols implicats en el consum de serveis web.</p></li><li><p>d) S&#39;han utilitzat els estàndards i arquitectures més difosos i implicats en el desenvolupament de serveis web.</p></li><li><p>e) S&#39;ha programat un servei web.</p></li><li><p>f) S&#39;ha verificat el funcionament del servei web.</p></li><li><p>g) S&#39;ha consumit el servei web.</p></li><li><p>h) S&#39;ha documentat un servei web.</p></li></ul><h4 id="ra8-genera-pagines-web-dinamiques-analitzant-i-utilitzant-tecnologies-i-frameworks-del-servidor-web-que-afigen-codi-al-llenguatge-de-marques" tabindex="-1">RA8. Genera pàgines web dinàmiques analitzant i utilitzant tecnologies i frameworks del servidor web que afigen codi al llenguatge de marques. <a class="header-anchor" href="#ra8-genera-pagines-web-dinamiques-analitzant-i-utilitzant-tecnologies-i-frameworks-del-servidor-web-que-afigen-codi-al-llenguatge-de-marques" aria-label="Permalink to &quot;RA8. Genera pàgines web dinàmiques analitzant i utilitzant tecnologies i frameworks del servidor web que afigen codi al llenguatge de marques.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han identificat les diferències entre l&#39;execució de codi en el servidor i en el client web.</p></li><li><p>b) S&#39;han reconegut els avantatges d&#39;unir totes dues tecnologies en el procés de desenvolupament de programes.</p></li><li><p>c) S&#39;han identificat les tecnologies i frameworks relacionades amb la generació per part del servidor de pàgines web amb guions embeguts.</p></li><li><p>d) S&#39;han utilitzat aquestes tecnologies i frameworks per a generar pàgines web que incloguen interacció amb l&#39;usuari.</p></li><li><p>e) S&#39;han utilitzat aquestes tecnologies i frameworks, per a generar pàgines web que incloguen verificació de formularis.</p></li><li><p>f) S&#39;han utilitzat aquestes tecnologies i frameworks per a generar pàgines web que incloguen modificació dinàmica del seu contingut i la seua estructura.</p></li><li><p>g) S&#39;han aplicat aquestes tecnologies i frameworks en la programació d&#39;aplicacions web.</p></li></ul><h4 id="ra9-desenvolupa-aplicacions-web-hibrides-seleccionant-i-utilitzant-tecnologies-frameworks-servidor-i-repositoris-heterogenis-d-informacio" tabindex="-1">RA9. Desenvolupa aplicacions web híbrides seleccionant i utilitzant tecnologies, frameworks servidor i repositoris heterogenis d&#39;informació. <a class="header-anchor" href="#ra9-desenvolupa-aplicacions-web-hibrides-seleccionant-i-utilitzant-tecnologies-frameworks-servidor-i-repositoris-heterogenis-d-informacio" aria-label="Permalink to &quot;RA9. Desenvolupa aplicacions web híbrides seleccionant i utilitzant tecnologies, frameworks servidor i repositoris heterogenis d&#39;informació.&quot;">​</a></h4><p><strong>Criteris d&#39;avaluació:</strong></p><ul><li><p>a) S&#39;han reconegut els avantatges que proporciona la reutilització de codi i l&#39;aprofitament d&#39;informació ja existent.</p></li><li><p>b) S&#39;han identificat tecnologies i frameworks aplicables en la creació d&#39;aplicacions web híbrides.</p></li><li><p>c) S&#39;ha creat una aplicació web que recupere i processe repositoris d&#39;informació ja existents.</p></li><li><p>d) S&#39;han creat repositoris específics a partir d&#39;informació existent en magatzems d&#39;informació.</p></li><li><p>e) S&#39;han utilitzat llibreries de codi i frameworks per a incorporar funcionalitats específiques a una aplicació web.</p></li><li><p>f) S&#39;han programat serveis i aplicacions web utilitzant com a base informació i codi generats per tercers.</p></li><li><p>g) S&#39;han analitzat i utilitzat llibreries de codi relacionades amb Big data i intel·ligència de negocis, per a incorporar anàlisis i intel·ligència de dades provinent de repositoris.</p></li><li><p>h) S&#39;han provat, depurat i documentat les aplicacions generades.</p></li></ul></details>',9)]))}const f=s(c,[["render",o]]);export{h as __pageData,f as default};
